INSERT INTO feature VALUES('type-codes','universes','Type codes and decoding',NULL,'implemented','uncommon','mainstream languages','A type is quoted as a code in a universe and decoded back: each computation into a universe, a call or a `match` among them, is read as the type of the code it returns where a type is expected; a call of a definition that runs to a variable''s call reads as that call, so the two convert. A type with no expression reading is written type(T) in expression position, the written quote beside the positional one. Where a computation is read, a type is written `return T`: a type atom and a type family''s application, a builtin former''s or a declared family''s, refuse there by their sort. A quoted session type''s payloads read no variable bound around the quote, as the kernel forms them; a run''s protocol, which stays on the checker''s side, may.','core-term core-checker kernel-core surface-lowering','corpus/model/desc/generic-arity.gandr corpus/model/sessions/type-quote.gandr corpus/pathological/sessions/type-quote.gandr corpus/model/universe/family-at-call.gandr corpus/model/universe/match-at-type.gandr corpus/model/universe/family-motive.gandr corpus/pathological/universe/family-motive.gandr','corpus/model/desc/generic-arity.gandr',NULL);
